SELECT "Generico_5"."Anunciante" AS "Datos__copia_",   MAX("Generico_5"."Vehiculo") AS "TEMP_attr_Vehiculo_nk__1662645443__0_",   MIN("Generico_5"."Vehiculo") AS "TEMP_attr_Vehiculo_nk__536654816__0_",   CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM(CAST("Generico_5"."NumAnuncios" AS BIGINT)) AS "sum_NumAnuncios_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE (("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (((CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) >= 2) AND (CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) <= 12)) OR (CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) IS NULL)) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) = 2015) AND ("Generico_5"."Medio" = 'TELEVISION NACIONAL')) GROUP BY "Generico_5"."Anunciante",   "mn_FECHA_ok",   "yr_FECHA_ok";
